{
  "criteria": [
    {
      "id": "EA-01",
      "dimension": "Planteamiento y tesis",
      "criterion": "Delimitación del problema y formulación de la tesis (k=4): valora que el tema esté acotado y que la introducción presente una postura clara, discutible y pertinente.",
      "levels": [
        {
          "level": 4,
          "description": "Delimita con precisión el problema, aporta el contexto necesario y formula una tesis específica, discutible y sostenida a lo largo del ensayo."
        },
        {
          "level": 3,
          "description": "Presenta un problema comprensible y una tesis clara, aunque la delimitación o el contexto podrían ser más precisos."
        },
        {
          "level": 2,
          "description": "Alude al tema, pero el problema es demasiado amplio o la tesis resulta general, descriptiva o poco discutible."
        },
        {
          "level": 1,
          "description": "No delimita el problema ni formula una postura reconocible; la introducción se limita a información general o tangencial."
        }
      ],
      "weight": 12,
      "evidence": "Título, primer y segundo párrafos de la introducción, y correspondencia entre la tesis anunciada y la postura mantenida en el resto del texto."
    },
    {
      "id": "EA-02",
      "dimension": "Desarrollo argumentativo",
      "criterion": "Pertinencia y suficiencia de las razones (k=4): examina si los argumentos principales sustentan directamente la tesis y cubren sus aspectos esenciales.",
      "levels": [
        {
          "level": 4,
          "description": "Desarrolla razones relevantes, diferenciadas y suficientes; cada una contribuye de manera identificable a defender la tesis."
        },
        {
          "level": 3,
          "description": "Ofrece varias razones pertinentes y generalmente suficientes, con alguna repetición o un aspecto importante poco desarrollado."
        },
        {
          "level": 2,
          "description": "Incluye razones limitadas, parcialmente repetidas o solo relacionadas de forma indirecta con la tesis."
        },
        {
          "level": 1,
          "description": "Presenta opiniones o afirmaciones sin razones identificables que permitan sostener la postura."
        }
      ],
      "weight": 12,
      "evidence": "Idea principal de cada párrafo de desarrollo y relación explícita de cada razón con la tesis formulada en la introducción."
    },
    {
      "id": "EA-03",
      "dimension": "Fuentes y respaldo",
      "criterion": "Calidad e integración de la evidencia (k=4): evalúa la credibilidad, variedad y actualidad de las fuentes, así como su incorporación al razonamiento propio.",
      "levels": [
        {
          "level": 4,
          "description": "Selecciona evidencia creíble, pertinente y suficiente; distingue datos, testimonios y ejemplos, y explica cómo respaldan cada afirmación."
        },
        {
          "level": 3,
          "description": "Usa fuentes generalmente confiables y pertinentes, aunque alguna evidencia necesita mayor explicación o diversidad."
        },
        {
          "level": 2,
          "description": "Aporta poca evidencia, depende de una sola fuente o incorpora citas y datos sin conectarlos claramente con los argumentos."
        },
        {
          "level": 1,
          "description": "Sostiene las afirmaciones principalmente con preferencias personales, generalizaciones o fuentes dudosas y no verificables."
        }
      ],
      "weight": 12,
      "evidence": "Citas, paráfrasis, estadísticas, ejemplos y estudios mencionados en el cuerpo del ensayo, contrastados con la lista de referencias."
    },
    {
      "id": "EA-04",
      "dimension": "Razonamiento crítico",
      "criterion": "Profundidad del análisis y validez de las inferencias (k=4): valora la explicación de relaciones causales o conceptuales y la ausencia de saltos lógicos.",
      "levels": [
        {
          "level": 4,
          "description": "Interpreta críticamente la evidencia, explicita supuestos y límites, y deriva conclusiones justificadas sin recurrir a falacias relevantes."
        },
        {
          "level": 3,
          "description": "Explica adecuadamente la mayoría de las inferencias, con algunos supuestos implícitos o relaciones que requieren mayor matiz."
        },
        {
          "level": 2,
          "description": "Predomina la descripción o la repetición de fuentes; hay generalizaciones apresuradas o conexiones causales insuficientemente justificadas."
        },
        {
          "level": 1,
          "description": "Las conclusiones no se derivan de lo presentado o dependen de falacias, contradicciones y afirmaciones sin explicación."
        }
      ],
      "weight": 10,
      "evidence": "Comentarios posteriores a cada dato o cita, conectores causales, supuestos declarados y pasajes donde se pasa de la evidencia a una inferencia."
    },
    {
      "id": "EA-05",
      "dimension": "Perspectivas y refutación",
      "criterion": "Tratamiento de objeciones y contraargumentos (k=4): considera si el autor representa con equidad otras posiciones y responde a sus objeciones más sólidas.",
      "levels": [
        {
          "level": 4,
          "description": "Formula una objeción relevante y verosímil, reconoce sus alcances y la refuta o matiza con razones y evidencia, sin falsear la posición contraria."
        },
        {
          "level": 3,
          "description": "Presenta y responde una objeción pertinente, aunque la refutación podría ser más completa o reconocer mejor sus límites."
        },
        {
          "level": 2,
          "description": "Menciona una posición contraria de forma superficial o la responde mediante afirmaciones generales con escaso respaldo."
        },
        {
          "level": 1,
          "description": "Ignora las objeciones previsibles o caricaturiza la posición contraria sin ofrecer una respuesta argumentada."
        }
      ],
      "weight": 10,
      "evidence": "Párrafo o sección dedicada a perspectivas alternativas, concesiones, refutaciones y fuentes empleadas para representarlas."
    },
    {
      "id": "EA-06",
      "dimension": "Organización global",
      "criterion": "Secuencia y equilibrio de la estructura (k=4): examina la progresión introducción-desarrollo-conclusión y la distribución del texto según la importancia de cada argumento.",
      "levels": [
        {
          "level": 4,
          "description": "Ordena las secciones de forma estratégica, mantiene una progresión clara y dedica un espacio proporcional a las ideas centrales."
        },
        {
          "level": 3,
          "description": "La estructura es reconocible y funcional, con algún cambio de orden o desequilibrio que no impide seguir el argumento."
        },
        {
          "level": 2,
          "description": "Hay saltos, repeticiones o secciones desproporcionadas que dificultan identificar la progresión general."
        },
        {
          "level": 1,
          "description": "Las ideas aparecen sin una secuencia discernible y la estructura no permite reconstruir el recorrido argumentativo."
        }
      ],
      "weight": 8,
      "evidence": "Orden de secciones y párrafos, extensión relativa de cada argumento, subtítulos cuando existan y correspondencia con el esquema de trabajo."
    },
    {
      "id": "EA-07",
      "dimension": "Coherencia local",
      "criterion": "Unidad de los párrafos y cohesión entre ideas (k=4): valora que cada párrafo desarrolle una idea central y que las transiciones expresen relaciones precisas.",
      "levels": [
        {
          "level": 4,
          "description": "Cada párrafo mantiene un foco claro; las transiciones naturales y los mecanismos de referencia hacen explícitas las relaciones entre ideas."
        },
        {
          "level": 3,
          "description": "La mayoría de los párrafos son unitarios y están enlazados, aunque algunas transiciones son mecánicas o poco informativas."
        },
        {
          "level": 2,
          "description": "Varios párrafos mezclan asuntos distintos o se conectan mediante enumeraciones y conectores repetitivos."
        },
        {
          "level": 1,
          "description": "Los enunciados parecen yuxtapuestos; faltan foco, referencias comprensibles y transiciones que orienten la lectura."
        }
      ],
      "weight": 8,
      "evidence": "Oraciones temáticas, inicios y cierres de párrafo, conectores, pronombres, reiteraciones léxicas y continuidad entre párrafos consecutivos."
    },
    {
      "id": "EA-08",
      "dimension": "Cierre argumentativo",
      "criterion": "Síntesis y alcance de la conclusión (k=4): evalúa si el cierre retoma la tesis a la luz del desarrollo y delimita sus implicaciones sin introducir afirmaciones desconectadas.",
      "levels": [
        {
          "level": 4,
          "description": "Sintetiza el recorrido sin copiarlo, reafirma o matiza la tesis con justificación y formula una implicación o apertura pertinente."
        },
        {
          "level": 3,
          "description": "Recupera la tesis y las razones principales con un cierre pertinente, aunque algo repetitivo o poco matizado."
        },
        {
          "level": 2,
          "description": "La conclusión es genérica, resume solo parcialmente o incorpora una recomendación poco vinculada con los argumentos."
        },
        {
          "level": 1,
          "description": "Falta un cierre reconocible o este contradice la postura, introduce un tema nuevo o termina abruptamente."
        }
      ],
      "weight": 7,
      "evidence": "Último párrafo, comparación de su formulación con la tesis inicial y verificación de que las implicaciones deriven del cuerpo del ensayo."
    },
    {
      "id": "EA-09",
      "dimension": "Estilo académico",
      "criterion": "Precisión léxica, tono y economía expresiva (k=4): considera un registro adecuado al propósito y lectores, evitando ambigüedad, grandilocuencia y redundancias.",
      "levels": [
        {
          "level": 4,
          "description": "Emplea vocabulario preciso, tono razonado y oraciones de complejidad variable; expresa matices sin recurrir a fórmulas vacías."
        },
        {
          "level": 3,
          "description": "Mantiene un registro apropiado y comprensible, con imprecisiones, repeticiones o muletillas ocasionales."
        },
        {
          "level": 2,
          "description": "Alterna tono coloquial y académico, abusa de tecnicismos o generalidades y presenta redundancias que restan claridad."
        },
        {
          "level": 1,
          "description": "El tono descalifica otras posiciones o el vocabulario es tan impreciso y reiterativo que compromete la comprensión."
        }
      ],
      "weight": 8,
      "evidence": "Elección de verbos y términos conceptuales, calificativos, muletillas, repeticiones, intensidad de las afirmaciones y adecuación al lector previsto."
    },
    {
      "id": "EA-10",
      "dimension": "Uso responsable de fuentes",
      "criterion": "Atribución y consistencia bibliográfica (k=4): comprueba que las ideas ajenas estén atribuidas y que las citas y referencias sigan de manera consistente el estilo solicitado.",
      "levels": [
        {
          "level": 4,
          "description": "Atribuye correctamente citas, paráfrasis y datos; integra las citas con fluidez y mantiene correspondencia y formato consistente en todas las referencias."
        },
        {
          "level": 3,
          "description": "La atribución y correspondencia son correctas en lo esencial, con errores menores de formato que no impiden localizar las fuentes."
        },
        {
          "level": 2,
          "description": "Hay omisiones de autor o fecha, referencias incompletas, inconsistencias frecuentes o paráfrasis demasiado cercanas al original."
        },
        {
          "level": 1,
          "description": "Presenta material ajeno sin atribución reconocible, fuentes imposibles de rastrear o una correspondencia bibliográfica muy deficiente."
        }
      ],
      "weight": 8,
      "evidence": "Citas textuales y paráfrasis, datos atribuibles, avisos dentro del texto, lista final de referencias y comparación con los originales consultados."
    },
    {
      "id": "EA-11",
      "dimension": "Corrección y presentación",
      "criterion": "Control gramatical y legibilidad formal (k=4): evalúa sintaxis, ortografía, puntuación y presentación sin confundir estos aspectos con la calidad del argumento.",
      "levels": [
        {
          "level": 4,
          "description": "El texto está cuidadosamente revisado; los eventuales deslices no afectan la lectura y el formato facilita localizar sus partes."
        },
        {
          "level": 3,
          "description": "Contiene algunos errores de gramática, puntuación o formato, pero el sentido permanece claro y la presentación es ordenada."
        },
        {
          "level": 2,
          "description": "Los errores son frecuentes o las oraciones mal delimitadas obligan a releer varios pasajes; el formato es irregular."
        },
        {
          "level": 1,
          "description": "La acumulación de problemas sintácticos, ortográficos o de presentación impide comprender con seguridad partes relevantes."
        }
      ],
      "weight": 5,
      "evidence": "Versión completa entregada, especialmente oraciones extensas, uso de comas y puntos, tildes, concordancia, márgenes, interlineado y uniformidad tipográfica."
    }
  ]
}

{
  "criteria": [
    {
      "id": "ARG-001",
      "dimension": "Planteamiento de la tesis",
      "criterion": "Formula una tesis clara, específica y discutible que responde directamente a la pregunta del ensayo.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: no presenta una tesis identificable o se limita a enunciar el tema.",
          "2 — Básico: expresa una postura general, pero resulta ambigua, demasiado amplia o poco discutible.",
          "3 — Competente: presenta una tesis clara y discutible, aunque su delimitación puede mejorar.",
          "4 — Avanzado: formula una tesis precisa, matizada y discutible que orienta todo el ensayo."
        ]
      },
      "weight": 12,
      "evidence": "Revisar el párrafo introductorio, especialmente la oración que explicita la postura, y comprobar su correspondencia con el desarrollo y la conclusión."
    },
    {
      "id": "ARG-002",
      "dimension": "Desarrollo de argumentos",
      "criterion": "Sustenta la tesis mediante argumentos pertinentes, suficientes y desarrollados, evitando la mera repetición de afirmaciones.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: ofrece opiniones sin argumentos o presenta ideas irrelevantes para la tesis.",
          "2 — Básico: incluye algunos argumentos pertinentes, pero son escasos, generales o apenas explicados.",
          "3 — Competente: desarrolla argumentos pertinentes y suficientes, con explicaciones generalmente claras.",
          "4 — Avanzado: articula argumentos sólidos y complementarios, explicando con profundidad por qué respaldan la tesis."
        ]
      },
      "weight": 12,
      "evidence": "Examinar la idea principal de cada párrafo de desarrollo y las explicaciones que vinculan cada argumento con la postura defendida."
    },
    {
      "id": "ARG-003",
      "dimension": "Uso de evidencia",
      "criterion": "Incorpora datos, ejemplos o fuentes pertinentes y fiables para respaldar los argumentos, sin sustituir el razonamiento por acumulación de citas.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: no aporta evidencia o utiliza información manifiestamente irrelevante o dudosa.",
          "2 — Básico: aporta evidencia limitada, poco precisa o solo parcialmente relacionada con los argumentos.",
          "3 — Competente: utiliza evidencia pertinente y fiable que respalda adecuadamente las afirmaciones principales.",
          "4 — Avanzado: selecciona e integra evidencia variada, precisa y fiable, interpretándola para fortalecer cada argumento."
        ]
      },
      "weight": 12,
      "evidence": "Inspeccionar datos, ejemplos, citas y referencias; verificar su pertinencia, atribución y relación explícita con las afirmaciones que pretenden sostener."
    },
    {
      "id": "ARG-004",
      "dimension": "Razonamiento lógico",
      "criterion": "Establece inferencias válidas entre la evidencia y las conclusiones, reconoce supuestos relevantes y evita falacias o generalizaciones indebidas.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: presenta saltos lógicos frecuentes, contradicciones o afirmaciones sin justificación.",
          "2 — Básico: mantiene una relación lógica parcial, pero incurre en generalizaciones o conexiones poco explicadas.",
          "3 — Competente: razona de manera coherente y justifica adecuadamente las inferencias principales.",
          "4 — Avanzado: construye inferencias rigurosas, examina supuestos y delimita sus afirmaciones para evitar conclusiones excesivas."
        ]
      },
      "weight": 10,
      "evidence": "Seguir las cadenas de razonamiento desde las premisas hasta la tesis, con atención a expresiones como 'por tanto', 'en consecuencia' y 'esto demuestra'."
    },
    {
      "id": "ARG-005",
      "dimension": "Contraargumentación",
      "criterion": "Representa con equidad una objeción relevante y responde a ella mediante refutación, concesión razonada o matización de la tesis.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: omite las objeciones o las presenta de forma caricaturizada.",
          "2 — Básico: menciona una postura contraria, pero no la explica ni responde de manera suficiente.",
          "3 — Competente: expone una objeción relevante y ofrece una respuesta razonada vinculada con la tesis.",
          "4 — Avanzado: formula la objeción en su versión más sólida y responde con matices, evidencia y reconocimiento de posibles límites."
        ]
      },
      "weight": 10,
      "evidence": "Localizar el apartado o párrafo de contraargumentos y evaluar tanto la fidelidad de su formulación como la calidad de la respuesta ofrecida."
    },
    {
      "id": "ARG-006",
      "dimension": "Organización del ensayo",
      "criterion": "Organiza la introducción, el desarrollo y la conclusión en una secuencia deliberada que facilita la comprensión y hace avanzar el argumento.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: carece de una estructura reconocible o dispone las ideas en un orden que dificulta seguir el texto.",
          "2 — Básico: presenta las partes básicas, pero con párrafos desordenados, redundantes o de función poco clara.",
          "3 — Competente: mantiene una estructura clara y una progresión generalmente lógica entre los párrafos.",
          "4 — Avanzado: ordena estratégicamente las secciones y párrafos, de modo que cada parte cumple una función y prepara la siguiente."
        ]
      },
      "weight": 10,
      "evidence": "Revisar la función de cada párrafo, el orden de los argumentos y la progresión desde la presentación del problema hasta la conclusión."
    },
    {
      "id": "ARG-007",
      "dimension": "Cohesión y transiciones",
      "criterion": "Conecta oraciones y párrafos mediante referencias claras y transiciones precisas que expresan relaciones de causa, contraste, adición o consecuencia.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: acumula ideas aisladas, con referentes ambiguos y escasos recursos de enlace.",
          "2 — Básico: usa conectores simples o repetitivos, pero algunas relaciones entre ideas quedan implícitas o confusas.",
          "3 — Competente: emplea referencias y transiciones adecuadas que permiten seguir el texto con fluidez.",
          "4 — Avanzado: integra recursos cohesionivos variados y precisos, haciendo explícitas las relaciones lógicas sin mecanizar el estilo."
        ]
      },
      "weight": 8,
      "evidence": "Examinar los inicios y cierres de párrafo, los conectores, las reiteraciones léxicas y los pronombres cuyo referente deba quedar claro."
    },
    {
      "id": "ARG-008",
      "dimension": "Conclusión",
      "criterion": "Cierra el ensayo sintetizando el recorrido argumentativo y respondiendo a la tesis, sin introducir afirmaciones centrales nuevas.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: falta la conclusión o esta resulta ajena al argumento desarrollado.",
          "2 — Básico: repite literalmente la introducción o formula un cierre general con escasa relación con el análisis.",
          "3 — Competente: retoma la tesis y sintetiza los argumentos principales con un cierre coherente.",
          "4 — Avanzado: reformula la tesis a la luz del análisis, integra sus resultados y señala con precisión una implicación o límite pertinente."
        ]
      },
      "weight": 6,
      "evidence": "Comparar el párrafo final con la tesis y los argumentos centrales; comprobar qué síntesis aporta y si añade contenido que debió desarrollarse antes."
    },
    {
      "id": "ARG-009",
      "dimension": "Lenguaje académico y estilo",
      "criterion": "Emplea un registro claro, preciso y apropiado para el propósito argumentativo, con vocabulario variado y un tono que evita descalificaciones.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: utiliza un registro inadecuado o un lenguaje impreciso que impide comprender varias ideas.",
          "2 — Básico: se comprende en general, pero presenta vaguedad, repeticiones, informalidad o afirmaciones excesivamente categóricas.",
          "3 — Competente: mantiene un registro académico claro y preciso, con vocabulario apropiado y tono respetuoso.",
          "4 — Avanzado: combina precisión conceptual, economía expresiva y matices adecuados, adaptando el estilo sin sacrificar naturalidad."
        ]
      },
      "weight": 8,
      "evidence": "Leer el texto completo atendiendo al vocabulario, la precisión de las afirmaciones, el tono hacia posiciones contrarias y la claridad de las oraciones."
    },
    {
      "id": "ARG-010",
      "dimension": "Citación e integridad académica",
      "criterion": "Atribuye correctamente las ideas y palabras ajenas, diferencia paráfrasis y citas directas y mantiene correspondencia entre las citas y las referencias.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: presenta contenido ajeno sin atribución o incluye referencias que no permiten identificar las fuentes.",
          "2 — Básico: reconoce algunas fuentes, pero comete omisiones, inconsistencias o paráfrasis demasiado próximas al original.",
          "3 — Competente: cita y parafrasea adecuadamente, con referencias completas y solo errores formales menores.",
          "4 — Avanzado: integra las fuentes con atribución precisa y consistente, distingue con claridad la voz propia y evita tanto la cita innecesaria como el plagio."
        ]
      },
      "weight": 8,
      "evidence": "Contrastar citas textuales, paráfrasis y datos con la lista de referencias; revisar autor, fecha, comillas y correspondencia entre citas internas y fuentes finales."
    },
    {
      "id": "ARG-011",
      "dimension": "Corrección formal y presentación",
      "criterion": "Respeta las consignas de extensión y formato y revisa gramática, ortografía y puntuación para que los errores no interfieran en la lectura.",
      "levels": {
        "k": 4,
        "ordered": [
          "1 — Inicial: incumple requisitos esenciales o contiene errores frecuentes que dificultan comprender el texto.",
          "2 — Básico: cumple parcialmente el formato y presenta errores recurrentes, aunque la mayoría de las ideas pueden seguirse.",
          "3 — Competente: cumple las consignas y muestra una revisión adecuada, con errores ocasionales que no afectan la comprensión.",
          "4 — Avanzado: presenta un texto cuidado, consistente y prácticamente libre de errores, con formato uniforme en todos sus elementos."
        ]
      },
      "weight": 4,
      "evidence": "Comprobar extensión, título, márgenes, interlineado y uniformidad tipográfica, además de revisar concordancia, tildes, comas, punto y coma y segmentación de oraciones."
    }
  ]
}
